function Assert-ProVolumeRequest($Request,$Owner){
 if($Request.caseId -cne $Owner.caseId -or $Request.nonce -cne $Owner.nonce -or $Request.ownerPid -ne $Owner.pid -or $Owner.pid -lt 1 -or $Owner.nonce -cnotmatch '^[a-f0-9]{64}$' -or $Request.phase -cne 'run' -or $Request.action -cnotin @('hold-foreign','release-foreign','hold-work','release-work')){throw 'Volume request binding changed'}
 foreach($value in @($Request.id,$Request.platformId,$Request.requestId)){$parsed=[guid]::Empty;if(-not [guid]::TryParseExact([string]$value,'D',[ref]$parsed) -or $parsed -eq [guid]::Empty -or $parsed.ToString('D') -cne $value){throw 'Canonical volume request identity required'}}
 if(@($Request.psobject.Properties.Name|Where-Object{$_ -notin @('caseId','phase','nonce','ownerPid','requestId','action','id','platformId')}).Count){throw 'Unexpected pressure request field'}
}
