 if($Config.container -ne ('C:\MuLab\private\volume-'+$caseId+'.vhdx') -or $Config.auxRoot -ne ('R:\MuVolume-'+$caseId) -or $Config.foreignDisk -ne (Join-Path $Config.auxRoot 'foreign.vhdx') -or [IO.Path]::GetFullPath($mapped.Path) -ne $Config.container -or $physical.IsBoot -or $physical.IsSystem -or [long]$physical.Size -ne 8GB -or $partition.DiskNumber -ne $physical.Number -or -not $container.Attached -or ([guid]$container.DiskIdentifier).ToString('D') -ne $Config.containerIdentifier -or $container.ParentPath){throw 'Auxiliary volume boundary changed'}
 if($vm.Name -ne ('mu-volume-witness-'+$caseId) -or $vm.Notes -ne ('MuCodeSandbox isolated volume witness '+$caseId) -or [string]$vm.State -ne 'Off' -or @(Get-VMNetworkAdapter -VM $vm).Count -or @(Get-VMSnapshot -VM $vm).Count -or $drives.Count -ne 1 -or [IO.Path]::GetFullPath($drives[0].Path) -ne $Config.foreignDisk -or [long]$disk.Size -ne 256GB -or $disk.ParentPath -or ([guid]$disk.DiskIdentifier).ToString('D') -ne $Config.foreignDiskIdentifier -or (Get-FileHash $Config.foreignDisk).Hash.ToLowerInvariant() -ne $Config.foreignSha256){throw 'Foreign stopped witness changed'}
