   if(Test-Path $resultFile){if(-not $handle.WaitForExit(15000) -or -not $agent.WaitForExit(45000)){throw 'Volume client or broker remains live'};$result=[IO.File]::ReadAllText($resultFile)|ConvertFrom-Json;if($result.caseId -ne $caseId -or $result.pid -ne $owner.pid -or $result.nonce -cne $owner.nonce){throw 'Volume terminal receipt changed'};$result|Add-Member -NotePropertyName processExitConfirmed -NotePropertyValue $true;$result|Add-Member -NotePropertyName brokerExitConfirmed -NotePropertyValue $true;$result|Add-Member -NotePropertyName witness -NotePropertyValue (& $checkWitness $config);[IO.File]::WriteAllText(($approved+'-'+$step+'-result.json'),($result|ConvertTo-Json -Depth 20),[Text.UTF8Encoding]::new($false));Unregister-ScheduledTask -TaskName $task -Confirm:$false;return $result}
   if($handle.HasExited){throw 'Volume owner exited without a result; preserve original resources'};if([DateTime]::UtcNow -gt $until){throw 'Volume phase unconfirmed; inspect its existing owner'};Start-Sleep -Milliseconds 100
  }while($true)}finally{foreach($item in @($held.Values)){$item.stream.Dispose();[IO.File]::Delete($item.file)}}
 }
}
